VOWELS = "aeiou"


def _translate_word(word):
    # Rule 1: starts with a vowel, "xr", or "yt"
    if word[0] in VOWELS or word.startswith(("xr", "yt")):
        return word + "ay"

    # Find the end of the leading consonant cluster.
    # "y" counts as a vowel once it is not the first letter (rule 4).
    i = 0
    while i < len(word) and word[i] not in VOWELS and not (word[i] == "y" and i > 0):
        i += 1

    # Rule 3: a "qu" right after the consonant cluster moves with it.
    if word[i - 1:i + 1] == "qu":
        i += 1

    # Rule 2: move the consonants to the end and add "ay".
    return word[i:] + word[:i] + "ay"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split(" "))

